SELECT RAWTOHEX(c.id) AS id, c.course_code AS courseCode, c.course_name AS courseName, c.term_code AS termCode, o.display_name AS ownerName, (SELECT COUNT(DISTINCT m.group_name) FROM edudoc_course_member m WHERE m.course_id = c.id AND m.status = 'A' AND m.group_name IS NOT NULL) AS groups, (SELECT COUNT(DISTINCT m.user_id) FROM edudoc_course_member m WHERE m.course_id = c.id AND m.member_role = 'STUDENT' AND m.status = 'A') AS students, (SELECT t.template_name FROM edudoc_template t WHERE t.course_id = c.id AND t.status = 'P' ORDER BY t.update_time DESC FETCH FIRST 1 ROWS ONLY) AS templateName, c.status AS status, (SELECT COUNT(*) FROM edudoc_assignment a WHERE a.course_id = c.id AND a.status = 'PUBLISHED' AND a.due_time BETWEEN SYSTIMESTAMP AND SYSTIMESTAMP + INTERVAL '7' DAY) AS dueWeek FROM edudoc_course c LEFT JOIN edudoc_user o ON o.id = c.teacher_id WHERE AND c.term_code = #{term} AND c.status = #{status}
AND (c.course_name LIKE '%' || #{keyword} || '%' OR c.course_code LIKE '%' || #{keyword} || '%')
ORDER BY c.term_code DESC, c.course_code OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

SELECT COUNT(*) FROM edudoc_course c
WHERE 
AND c.term_code = #{term}
AND c.status = #{status}

    AND (c.course_name LIKE '%' || #{keyword} || '%' OR c.course_code LIKE '%' || #{keyword} || '%')

SELECT RAWTOHEX(id) FROM edudoc_submission
WHERE assignment_id = HEXTORAW(#{assignmentIdHex}) AND student_id = HEXTORAW(#{studentIdHex})
  AND attempt_no = #{attemptNo}

